# random_future_revision.py <generated by GitHub Copilot>
#
# Pulls one random card from the 20 cards with the furthest next
# repetition time and makes it due immediately when Mnemosyne starts.

import random

from mnemosyne.libmnemosyne.hook import Hook
from mnemosyne.libmnemosyne.plugin import Plugin

number_of_cards_to_consider = 20


class RandomFutureRevisionHook(Hook):

    used_for = "after_load"

    def run(self):
        db = self.database()
        if not db or not db.is_loaded():
            return

        scheduler = self.scheduler()
        if not scheduler:
            return

        rows = db.con.execute(
            """select _id from cards
                where active=1 and grade>=2
                order by next_rep desc
                limit ?""", (number_of_cards_to_consider, )).fetchall()
        if not rows:
            return

        card_id = random.choice([row[0] for row in rows])
        card = db.card(card_id, is_id_internal=True)
        due = scheduler.adjusted_now()
        if card.next_rep > due:
            card.next_rep = due
            db.update_card(card)


class RandomFutureRevisionPlugin(Plugin):

    name = "Random future revision on startup"
    description = (
        "On startup, choose a random card from the 20 cards with the "
        "furthest next repetition date and make it due immediately."
    )
    components = [RandomFutureRevisionHook]
    supported_API_level = 3


# Register plugin.

from mnemosyne.libmnemosyne.plugin import register_user_plugin
plugin = register_user_plugin(RandomFutureRevisionPlugin)
plugin.activate()
